1	export type Item = {
2	  type: string;
3	};
4	
5	export type Scenario = {
6	  customer: { yearsWithMHPCO: number };
7	  steps: { op: string; items: Item[] }[];
8	};
9	
10	export type ScenarioResult = {
11	  results: { premium: number }[];
12	};
13	
14	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
15	  sword: 100,
16	  amulet: 60,
17	  staff: 80,
18	  potion: 40,
19	  rune: 25,
20	};
21	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
22	const PROCESSING_FEE = 5;
23	
24	const percentOf = (amount: number, percent: number): number =>
25	  (amount * percent) / 100;
26	
27	const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
28	
29	const policyBasePremium = (items: Item[]): number =>
30	  items.reduce((sum, item) => sum + BASE_PREMIUM_BY_ITEM_TYPE[item.type], 0);
31	
32	const quotePremium = (items: Item[]): number => {
33	  const basePremium = policyBasePremium(items);
34	  const withFirstInsuranceSurcharge =
35	    basePremium + percentOf(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
36	  return roundInMHPCOsFavour(withFirstInsuranceSurcharge + PROCESSING_FEE);
37	};
38	
39	export const runScenario = (scenario: Scenario): ScenarioResult => ({
40	  results: scenario.steps.map((step) => ({
41	    premium: quotePremium(step.items),
42	  })),
43	});
